/**
 * The Vite side of the licence notices (notices.ts does the work).
 *
 * noticesCollector watches what Rollup actually bundles, in the app build
 * and in its Web Worker builds, and writes acknowledgements.json and
 * THIRD-PARTY-NOTICES.txt into the app's dist. It lives here, not in a
 * Taskfile, because build/Taskfile.yml and build/darwin/Taskfile.yml are
 * regenerated by `update:build-assets`; this file is not.
 *
 * noticesCheck is for the Quick Look build, which runs after the app's: it
 * fails if Quick Look bundles a package the app's notices do not list.
 */
import { execFileSync } from 'node:child_process'
import { existsSync, readFileSync } from 'node:fs'
import { join, resolve } from 'node:path'
import { fileURLToPath } from 'node:url'
import type { Plugin, Rollup } from 'vite'
import {
  applyElections,
  checkOverrides,
  collectNpm,
  goEntries,
  missingFrom,
  packageOf,
  renderText,
  sortEntries,
  type Notices,
} from './notices'

const REPO_ROOT = resolve(fileURLToPath(new URL('.', import.meta.url)), '../../..')

type GoModule = { path: string; version: string; dir: string }

export type CollectorOptions = {
  overridesDir: string
  licencesDir: string
  goModules: () => GoModule[]
  goroot: () => string
  goVersion: () => string
}

const go = (args: string[]) => execFileSync('go', args, { cwd: REPO_ROOT, encoding: 'utf8' }).trim()

/**
 * The modules linked into the app, from `go list -deps` on the main package,
 * with and without the production tag: release and package builds use it,
 * dev builds do not and link one more module (go-isatty, for Wails' dev
 * logging). The paid-features switch is a tag too, but the paid code stays
 * in both builds, so it does not change this list.
 */
function listGoModules(): GoModule[] {
  const format = '{{with .Module}}{{if not .Main}}{{.Path}} {{.Version}} {{.Dir}}{{end}}{{end}}'
  const out = [['-tags', 'production'], []].map((tags) => go(['list', '-deps', ...tags, '-f', format, '.'])).join('\n')
  const seen = new Map<string, GoModule>()
  for (const line of out.split('\n')) {
    const [path, version, ...dir] = line.trim().split(' ')
    if (path && !seen.has(path)) seen.set(path, { path, version, dir: dir.join(' ') })
  }
  return [...seen.values()]
}

const defaults: CollectorOptions = {
  overridesDir: join(REPO_ROOT, 'licenses', 'overrides'),
  licencesDir: join(REPO_ROOT, 'licenses'),
  goModules: listGoModules,
  goroot: () => go(['env', 'GOROOT']),
  goVersion: () => go(['env', 'GOVERSION']),
}

/**
 * The module ids a bundle really contains: modules with rendered code
 * (tree-shaken ones have none) and the files assets were made from, such as
 * a package's fonts and stylesheets.
 */
function bundledIds(bundle: Rollup.OutputBundle): string[] {
  const ids: string[] = []
  for (const item of Object.values(bundle)) {
    if (item.type === 'chunk') {
      for (const [id, m] of Object.entries(item.modules)) if (m.renderedLength > 0) ids.push(id)
    } else {
      ids.push(...(item.originalFileNames ?? []))
    }
  }
  return ids
}

export function noticesCollector(options: Partial<CollectorOptions> = {}) {
  const o = { ...defaults, ...options }
  const ids = new Set<string>()
  const collect = (bundle: Rollup.OutputBundle) => bundledIds(bundle).forEach((id) => ids.add(id))

  const worker = (): Plugin => ({
    name: 'halmos-notices-worker',
    apply: 'build',
    generateBundle(_, bundle) {
      collect(bundle)
    },
  })

  const plugin = (): Plugin => ({
    name: 'halmos-notices',
    apply: 'build',
    // Workers are bundled while the app's chunks are rendered, so by the
    // time the app's generateBundle runs their modules are already in ids.
    generateBundle(_, bundle) {
      collect(bundle)
      const npm = collectNpm(ids, o.overridesDir)
      checkOverrides(
        new Set(npm.flatMap((e) => (e.override ? [e.override] : []))),
        o.overridesDir,
        new Set(npm.filter((e) => !e.override).map((e) => `${e.name}@${e.version}`)),
      )
      const notices: Notices = {
        generatedBy: 'halmos-notices',
        entries: sortEntries([...npm, ...goEntries(o.goModules(), o.goroot(), o.goVersion())]).map((e) =>
          applyElections(e, o.licencesDir),
        ),
      }
      this.emitFile({ type: 'asset', fileName: 'acknowledgements.json', source: JSON.stringify(notices) })
      this.emitFile({ type: 'asset', fileName: 'THIRD-PARTY-NOTICES.txt', source: renderText(notices) })
    },
  })

  return { plugin, worker }
}

export function noticesCheck(appDist: string): Plugin {
  return {
    name: 'halmos-notices-check',
    apply: 'build',
    generateBundle(_, bundle) {
      const file = join(appDist, 'acknowledgements.json')
      if (!existsSync(file)) this.error(`${file} is missing: build the app's frontend before Quick Look`)
      const notices = JSON.parse(readFileSync(file, 'utf8')) as Notices
      const packages = new Map<string, { name: string; version: string }>()
      for (const id of bundledIds(bundle)) {
        const p = packageOf(id)
        if (!p || packages.has(p.dir)) continue
        const pkg = JSON.parse(readFileSync(join(p.dir, 'package.json'), 'utf8')) as { name: string; version: string }
        packages.set(p.dir, { name: pkg.name, version: pkg.version })
      }
      const missing = missingFrom(notices, [...packages.values()])
      if (missing.length) {
        this.error(`Quick Look bundles packages the app's licence notices do not list: ${missing.join(', ')}`)
      }
    },
  }
}
